from app import gateway


def pay(account_id, cents):
    try:
        receipt = gateway.charge(account_id, cents)
    except gateway.GatewayTimeout:
        # The processor may or may not have completed the charge, so do not
        # retry here: gateway.charge takes no idempotency key and a retry
        # could charge the card twice. Report the outcome as unknown instead.
        return {"status": "pending", "receipt": None}
    return {"status": "paid", "receipt": receipt}

