from app import gateway, queue


def pay(account_id, cents):
    try:
        receipt = gateway.charge(account_id, cents)
    except gateway.GatewayTimeout:
        # The processor may or may not have taken the charge, so do not retry
        # here (that could double-charge). Report it as pending and queue a
        # job to find out what actually happened.
        queue.enqueue(
            "payment-reconcile", {"account_id": account_id, "cents": cents}
        )
        return {"status": "pending", "receipt": None}
    return {"status": "paid", "receipt": receipt}

